changeSet.sql:
CREATE SEQUENCE account_claim_seq MINVALUE 0 MAXVALUE 999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 1 NO CYCLE;

CREATE TABLE IF NOT EXISTS "account_claim"
(
    "id"  BIGINT NOT NULL,
"account_identifier" BIGINT,
"request_id" BIGINT,
CONSTRAINT "pk_account_claim" PRIMARY KEY("id")
);

COMMENT ON TABLE "account_claim" is 'Represents a completed account claim process.';

COMMENT ON COLUMN "account_claim"."id" is 'Primary key.';
COMMENT ON COLUMN "account_claim"."account_identifier" IS 'The account identifier.';
COMMENT ON COLUMN "account_claim"."request_id" is 'The request identifier.';
